From 053beb117c70d2e710715bcbfbc612370b878e26 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:23:53 +0100
Subject: [PATCH] containments/desktop: show desktop file names in any local
 folder

Only desktop:/ showed .desktop files by their Name, so a Folder View
set to any other folder listed them as "foo.desktop". Do the same for
local folders: show, sort and rename them by Name, like on the desktop.

BUG: 448884
---
 .../package/contents/ui/FolderView.qml        |  2 +-
 .../desktop/plugins/folder/foldermodel.cpp    | 48 +++++++++++++++++--
 .../desktop/plugins/folder/foldermodel.h      |  3 ++
 3 files changed, 49 insertions(+), 4 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..4cee155b6a 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1228,7 +1228,7 @@ FocusScope {
             usedByContainment: root.isContainment && main.isRootView
             sortDesc: Plasmoid.configuration.sortDesc
             sortDirsFirst: Plasmoid.configuration.sortDirsFirst
-            parseDesktopFiles: (Plasmoid.configuration.url === "desktop:/")
+            parseDesktopFiles: Plasmoid.configuration.url === "desktop:/" || resolvedUrl.toString().startsWith("file:")
             previews: Plasmoid.configuration.previews
             previewPlugins: Plasmoid.configuration.previewPlugins
             applet: Plasmoid
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..bbf9fd105a 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -225,6 +225,12 @@ FolderModel::FolderModel(QObject *parent)
     dirLister->setAutoErrorHandlingEnabled(false);
     connect(dirLister, &DirLister::error, this, &FolderModel::dirListFailed);
     connect(dirLister, &KCoreDirLister::itemsDeleted, this, &FolderModel::evictFromIsDirCache);
+    connect(dirLister, &KCoreDirLister::refreshItems, this, [this](const QList<QPair<KFileItem, KFileItem>> &items) {
+        for (const auto &[oldItem, newItem] : items) {
+            m_desktopNameCache.remove(oldItem.url());
+            m_desktopNameCache.remove(newItem.url());
+        }
+    });

     connect(dirLister, &KCoreDirLister::started, this, std::bind(&FolderModel::setStatus, this, Status::Listing));

@@ -436,6 +442,7 @@ void FolderModel::setUrl(const QString &url)
     beginResetModel();
     m_url = url;
     m_isDirCache.clear();
+    m_desktopNameCache.clear();
     m_dirModel->dirLister()->openUrl(resolvedNewUrl);
     clearDragImages();
     m_dragIndexes.clear();
@@ -933,7 +940,18 @@ void FolderModel::rename(int row, const QString &name)
     }

     const KFileItem oldItem = itemForIndex(idx);
-    if (name.isEmpty() || name == oldItem.text() || name == QLatin1Char('.') || name == QLatin1String("..")) {
+    if (name.isEmpty() || name == itemText(oldItem) || name == QLatin1Char('.') || name == QLatin1String("..")) {
+        return;
+    }
+
+    if (isLocalDesktopFile(oldItem)) {
+        KDesktopFile file(oldItem.localPath());
+        KConfigGroup group = file.desktopGroup();
+        group.writeEntry("Name", name);
+        group.writeEntry("Name", name, KConfigGroup::Persistent | KConfigGroup::Localized);
+        group.sync();
+        m_desktopNameCache.remove(oldItem.url());
+        Q_EMIT dataChanged(idx, idx, {Qt::DisplayRole, FileNameWrappedRole});
         return;
     }

@@ -1575,7 +1593,9 @@ QVariant FolderModel::data(const QModelIndex &index, int role) const
     } else if (role == FileNameRole) {
         return itemForIndex(index).url().fileName();
     } else if (role == FileNameWrappedRole) {
-        return KStringHandler::preProcessWrap(itemForIndex(index).text());
+        return KStringHandler::preProcessWrap(itemText(itemForIndex(index)));
+    } else if (role == Qt::DisplayRole && index.column() == 0) {
+        return itemText(itemForIndex(index));
     }

     return QSortFilterProxyModel::data(index, role);
@@ -1659,11 +1679,33 @@ void FolderModel::statResult(KJob *job)
     m_isDirJobs.remove(url);
 }

+bool FolderModel::isLocalDesktopFile(const KFileItem &item) const
+{
+    // desktop:/ items already get the desktop file's name from the worker
+    return m_parseDesktopFiles && item.url().isLocalFile() && item.isDesktopFile();
+}
+
+QString FolderModel::itemText(const KFileItem &item) const
+{
+    if (isLocalDesktopFile(item)) {
+        auto it = m_desktopNameCache.constFind(item.url());
+        if (it == m_desktopNameCache.constEnd()) {
+            it = m_desktopNameCache.insert(item.url(), KDesktopFile(item.localPath()).readName());
+        }
+        if (!it->isEmpty()) {
+            return *it;
+        }
+    }
+
+    return item.text();
+}
+
 void FolderModel::evictFromIsDirCache(const KFileItemList &items)
 {
     for (const KFileItem &item : items) {
         m_screenMapper->removeFromMap(item.url(), m_currentActivity);
         m_isDirCache.remove(item.url());
+        m_desktopNameCache.remove(item.url());
         Q_EMIT itemDeleted(item.url());
     }
 }
@@ -1733,7 +1775,7 @@ bool FolderModel::lessThan(const QModelIndex &left, const QModelIndex &right) co

     QCollator collator;

-    result = collator.compare(leftItem.text(), rightItem.text());
+    result = collator.compare(itemText(leftItem), itemText(rightItem));

     if (result != 0)
         return result < 0;
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..a0a946d2cc 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -267,6 +267,8 @@ public:
     int indexForUrl(const QUrl &url) const;
     KFileItem itemForIndex(const QModelIndex &index) const;
     bool isDir(const QModelIndex &index, const KDirModel *dirModel) const;
+    QString itemText(const KFileItem &item) const;
+    bool isLocalDesktopFile(const KFileItem &item) const;
     bool lessThan(const QModelIndex &left, const QModelIndex &right) const override;
     Qt::DropActions supportedDragActions() const override;
     Qt::DropActions supportedDropActions() const override;
@@ -372,6 +374,7 @@ private:
     KDirWatch *m_dirWatch;
     QString m_url;
     mutable QHash<QUrl, bool> m_isDirCache;
+    mutable QHash<QUrl, QString> m_desktopNameCache;
     mutable QHash<QUrl, KIO::StatJob *> m_isDirJobs;
     QItemSelectionModel *m_selectionModel;
     QItemSelection m_pinnedSelection;
-- 
